  }
}

class Motif {
  constructor(props) {
    this.id = props.id ?? 0;
    this.isDisplay = props.isDisplay ?? true;
    this.originX = props.originX ?? 0;
    this.originY = props.originY ?? 0;
    this.x = props.x ?? 0;
    this.y = props.y ?? 0;
    this.size = props.size ?? 100;
    this.w = props.w ?? 100;
    this.h = props.h ?? 100;
    this.scaleX = props.scaleX ?? 1.0;
    this.scaleY = props.scaleY ?? 1.0;
    this.angle = props.angle ?? 0;
    this.rotationSpeed = props.rotationSpeed ?? 0.005;
    this.rotationDirection = props.rotationDirection ?? 1;
    this.numPoints = props.numPoints ?? 300;
    this.radius = props.radius ?? 200;
    this.elements = [];
    for (let i = 0; i < this.numPoints; i++) {
      const ang = (i * TWO_PI) / this.numPoints;
      const px = this.radius * cos(ang);
      const py = this.radius * sin(ang);
      const element = new Element({
        id: i,
        x: px,
        y: py,
        angle: ang,
        radius: this.radius,
        rotationDirection: this.rotationDirection
      });
      this.elements.push(element);
    }
  }

  run = () => {
    if (!this.isDisplay) return;
    this.angle += this.rotationSpeed * this.rotationDirection;
    push();
    translate(this.originX, this.originY);
    rotate(this.angle);
    for (let i = 0; i < this.elements.length; i++) {
      var element = this.elements[i];
      var ang = (i * TWO_PI) / this.numPoints + this.angle;
      element.x = this.radius * cos(ang);
      element.y = this.radius * sin(ang);
    }
    pop();
  }

  getElement = (index) => {
    return this.elements[index];
  }

  getPosition = () => {
    return { x: this.originX, y: this.originY };
  }
}

class Module {
  constructor(props = {}) {
    this.isDisplay = props.isDisplay ?? true;
    this.originX = props.originX ?? 0;
    this.originY = props.originY ?? 0;
    this.angle = 0;
    this.angleAccel = 0.006;
    this.numPoints = 360;
    this.radius = 200;
    this.spacing = 280;
    this.rotationSpeed = 0.012;
    this.noiseOffset = random(1000);
    this.numCircles = 4;
    this.motifs = [];

    for (let i = 0; i < this.numCircles; i++) {
      const angle = (i * TWO_PI) / this.numCircles - PI/2;
      const x = this.spacing * cos(angle);
      const y = this.spacing * sin(angle);
      const motif = new Motif({
        originX: x,
        originY: y,
        radius: this.radius,
        numPoints: this.numPoints,
        rotationDirection: i % 2 === 0 ? 1 : -1,
        rotationSpeed: this.rotationSpeed
      });
      this.motifs.push(motif);
    }
  }

  run = () => {
    if (!this.isDisplay) return;
    push();
    translate(this.originX, this.originY);
    this.angle += this.angleAccel;
    rotate(this.angle);
    this.motifs.forEach(motif => motif.run());

    for (let i = 0; i < this.numCircles; i++) {
      this.drawConnectionLines(
        this.motifs[i], 
        this.motifs[(i + 1) % this.numCircles], 
        i * 1000
      );
    }
    this.noiseOffset += 0.006;
    pop();
  }

  drawConnectionLines(motif1, motif2, noiseOffsetAdd) {
    let beatVal = window.beatEnergy || 0.0;
    let audioVal = window.audioLow || 0.5;
    let weightScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;

    for (let i = 0; i < this.numPoints; i += 2) { // 每隔 2 點連線以提升效能
      const element1 = motif1.getElement(i);
      const element2 = motif2.getElement(i);
      const pos1 = element1.getPosition();
      const pos2 = element2.getPosition();
      const motif1Pos = motif1.getPosition();
      const motif2Pos = motif2.getPosition();

      const pos1Global = {
        x: pos1.x + motif1Pos.x,
        y: pos1.y + motif1Pos.y
      };
      const pos2Global = {
        x: pos2.x + motif2Pos.x,
        y: pos2.y + motif2Pos.y
      };

      const noiseVal1 = noise(i * 0.04, this.noiseOffset + noiseOffsetAdd);
      const noiseVal2 = noise(i * 0.04, this.noiseOffset + noiseOffsetAdd + 100);

      const midX = (pos1Global.x + pos2Global.x) / 2;
      const midY = (pos1Global.y + pos2Global.y) / 2;

      // 變種特點: 貝茲控制點偏移範圍隨音樂跳動
      const cpOffset = 50 + beatVal * 150;
      const cp1x = midX + map(noiseVal1, 0, 1, -cpOffset, cpOffset);
      const cp1y = midY + map(noiseVal2, 0, 1, -cpOffset, cpOffset);

      const sw = map(noise(i * 0.08, this.noiseOffset), 0, 1, 0.6, 2.2) * weightScale;
      strokeWeight(sw);

      // 變種特點: 炫彩霓虹漸變色織帶
      colorMode(HSB, 360, 100, 100, 1.0);
      let h = (map(i, 0, this.numPoints, 0, 360) + frameCount * 0.4) % 360;
      if (window.currentChordColor) {
        let chordC = color(window.currentChordColor);
        let chordH = hue(chordC);
        h = lerp(h, chordH, 0.4);
      }

      stroke(h, 92, 95, 0.38);

      bezier(
        pos1Global.x, pos1Global.y,
        cp1x, cp1y,
        cp1x, cp1y,
        pos2Global.x, pos2Global.y
      );
    }
  }
}

